async function handlePrivacy() {
  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>ContextCut PRO — Privacy Policy</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0F172A;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;padding:32px 24px;color:#CBD5E1}
.card{background:#1E293B;border:1px solid #334155;border-radius:12px;max-width:680px;margin:0 auto;overflow:hidden}
.hdr{background:#0EA5E9;padding:28px 32px}
.hdr h1{color:#fff;font-size:20px;font-weight:700}
.hdr p{color:#E0F2FE;font-size:13px;margin-top:6px}
.bdy{padding:28px 32px}
.sec{margin-bottom:28px}
.sec h2{color:#0EA5E9;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:10px}
.sec p{font-size:14px;color:#94A3B8;line-height:1.8;margin-bottom:8px}
.sec ul{margin:6px 0 8px 18px}
.sec li{font-size:14px;color:#94A3B8;line-height:1.8}
.badge{display:inline-block;background:#0F172A;border:1px solid #22C55E;border-radius:6px;padding:6px 14px;font-size:12px;color:#22C55E;margin-top:6px}
.foot{text-align:center;padding:20px 32px;border-top:1px solid #334155;font-size:12px;color:#64748B}
.foot a{color:#0EA5E9;text-decoration:none}
</style>
</head>
<body>
<div class="card">
  <div class="hdr">
    <h1>Privacy Policy</h1>
    <p>ContextCut PRO &mdash; Effective date: 2025</p>
  </div>
  <div class="bdy">

    <div class="sec">
      <h2>The short version</h2>
      <p>ContextCut PRO runs entirely on your machine. Your documents, queries, and AI responses never leave your hardware. We collect nothing about how you use the software.</p>
      <span class="badge">&#10003; No telemetry &nbsp; &#10003; No analytics &nbsp; &#10003; No cloud storage</span>
    </div>

    <div class="sec">
      <h2>What we collect</h2>
      <p>The only data that reaches our servers is:</p>
      <ul>
        <li><strong>License key</strong> &mdash; a UUID generated at purchase, used to verify your seat is active</li>
        <li><strong>Machine fingerprint</strong> &mdash; your machine hostname, used to track which seats are active under your license. Never linked to your identity.</li>
        <li><strong>Heartbeat timestamp</strong> &mdash; a ping every 15 minutes to keep your seat active. Contains only the license key and instance ID.</li>
      </ul>
      <p style="margin-top:8px">No document content, filenames, query text, model responses, or usage metrics are ever transmitted.</p>
    </div>

    <div class="sec">
      <h2>What we do not collect</h2>
      <ul>
        <li>Document or knowledge base content</li>
        <li>LLM queries or responses</li>
        <li>IP addresses beyond what Cloudflare logs for DDoS protection (not stored by us)</li>
        <li>Usage statistics, session data, or analytics</li>
        <li>Crash reports or error telemetry</li>
      </ul>
    </div>

    <div class="sec">
      <h2>Third-party services</h2>
      <p><strong>Voyage AI</strong> &mdash; Optional. If you provide a Voyage AI API key, document content is sent to Voyage AI for embedding generation. Voyage AI states they do not store or train on document content. Review their privacy policy at voyageai.com.</p>
      <p style="margin-top:8px"><strong>Ollama</strong> &mdash; Runs locally on your hardware. No data leaves your machine via Ollama unless you configure a remote Ollama endpoint yourself.</p>
      <p style="margin-top:8px"><strong>Cloudflare</strong> &mdash; Our license server runs on Cloudflare Workers. Cloudflare may log request metadata (IP, timestamp) per their standard infrastructure logging. We do not access or store these logs.</p>
    </div>

    <div class="sec">
      <h2>Data retention</h2>
      <p>License records (key + seat fingerprints) are retained in Cloudflare KV for the lifetime of your license. On refund or revocation, all records are deleted within 24 hours.</p>
      <p style="margin-top:8px">All other data &mdash; your documents, queries, logs &mdash; resides on your machine under your control.</p>
    </div>

    <div class="sec">
      <h2>Your rights</h2>
      <p>To request deletion of your license record, email <a href="mailto:support@contextcut-pro.com" style="color:#0EA5E9">support@contextcut-pro.com</a> with your license key. Records are deleted within 48 hours.</p>
    </div>

    <div class="sec">
      <h2>Contact</h2>
      <p><a href="mailto:support@contextcut-pro.com" style="color:#0EA5E9">support@contextcut-pro.com</a></p>
      <p style="margin-top:6px"><a href="/compliance/soc2" style="color:#0EA5E9">Security &amp; Privacy Self-Assessment &rarr;</a></p>
    </div>

  </div>
  <div class="foot">
    <a href="/promo">ContextCut PRO</a> &nbsp;&middot;&nbsp; <a href="mailto:support@contextcut-pro.com">Contact</a> &nbsp;&middot;&nbsp; <a href="https://github.com/StevoKeano/ContextCut-PRO">Docs</a>
  </div>
</div>
</body>
</html>`;
  return new Response(html, {
    headers: { "Content-Type": "text/html;charset=UTF-8" },
  });
}

function json(status, data) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname === "/favicon.ico") {
      return new Response(null, { status: 204 });
    }

    if (url.pathname === "/health") {
      try {
        await env.LICENSE_KV.get("health_check");
        return json(200, { status: "healthy", kv: "ok", uptime: "ok" });
      } catch (e) {
        return json(500, { status: "unhealthy", error: e.message });
      }
    }

    if (url.pathname === "/webhook/gumroad" && request.method === "POST") {
      return await handleWebhook(request, env);
    }

    if (url.pathname === "/install.js") {
      return await handleInstallScript();
    }

    if (url.pathname === "/compliance/soc2") {
      return await handleCompliance();
    }

    if (url.pathname === "/privacy") {
      return await handlePrivacy();
    }

    if (url.pathname === "/promo") {
      return await handlePromo();
    }

    const installMatch = url.pathname.match(/^\/install\/(CC-PRO-[a-f0-9-]+)$/);
    if (installMatch) {
      return await handleInstallLink(request, env, installMatch[1]);
    }

    if (url.pathname === "/v1/license/validate" && request.method === "POST") {
      return await handleValidate(request, env);
    }
    if (url.pathname === "/v1/heartbeat" && request.method === "POST") {
      return await handleHeartbeat(request, env);
    }
    if (url.pathname === "/v1/license/release" && request.method === "POST") {
      return await handleRelease(request, env);
    }
    if (url.pathname === "/v1/license/reset" && request.method === "POST") {
      return await handleReset(request, env);
    }

    return new Response("Not found", { status: 404 });
  },
};
